1	/**
2	 * HK-1: runs one command hook as a subprocess and reduces what it answered to a decision.
3	 *
4	 * The process gets the event as one JSON object on standard input, a scrubbed environment (no credentials of the
5	 * Nexus process), its own process group and a hard deadline. Its answer can only deny: `reduceHookOutput` has no
6	 * path from any output to "admit what was refused", and everything that goes wrong is a denial.
7	 */
8	import { spawn } from "node:child_process";
9	import { createHash } from "node:crypto";
10	import * as os from "node:os";
11	import * as path from "node:path";
12	import { buildMcpEnvironment } from "../mcp.js";
13	import type { HookDenialReason, HookEvent, HookSource } from "./hooks.js";
14	import { ProcessTreeMemory } from "./process_identity.js";
15	import { parseStrictJson } from "./strict_json.js";
16	
17	export const HOOK_STDOUT_LIMIT = 64 * 1024;
18	export const HOOK_STDERR_LIMIT = 8 * 1024;
19	/** Time a hook gets after SIGTERM before it and everything it started is killed. */
20	export const HOOK_KILL_GRACE_MS = 2_000;
21	/** Time a hook's output pipes may stay open after it exited (something it started still holds them). */
22	export const HOOK_DRAIN_MS = 2_000;
23	const REASON_LIMIT = 1000;
24	
25	export type HookFailure = "spawn" | "timeout" | "stdout_oversize" | "stderr_oversize" | "output_left_open";
26	
27	export interface HookProcessResult {
28	  exit: number | null;
29	  signal: string | null;
30	  stdout: string;
31	  stderr: string;
32	  /** Set when the run did not end as an ordinary exit with complete, bounded output. */
33	  failure?: HookFailure;
34	  detail?: string;
35	  durationMs: number;
36	}
37	
38	export interface HookProcessRequest {
39	  /** A string runs under `/bin/sh -c`; an array is executed directly. */
40	  command: string | string[];
41	  cwd: string;
42	  env: Record<string, string>;
43	  stdin: string;
44	  timeoutMs: number;
45	  killGraceMs?: number;
46	  drainMs?: number;
47	}
48	
49	/** The environment of a hook: the MCP server scrubber's safe variables plus the hook's own, and nothing else. */
50	export function hookEnvironment(hook: { event: HookEvent; name: string; source: HookSource; workspace: string }): Record<string, string> {
51	  return buildMcpEnvironment({
52	    NEXUS_HOOK_EVENT: hook.event,
53	    NEXUS_HOOK_NAME: hook.name,
54	    NEXUS_HOOK_SOURCE: hook.source,
55	    NEXUS_PROJECT_DIR: hook.workspace,
56	    CLAUDE_PROJECT_DIR: hook.workspace,
57	  });
58	}
59	
60	/** One line, bounded: what a hook said, safe to show and to store. */
61	export function hookLine(text: string, limit = REASON_LIMIT): string {
62	  const line = text.replace(/[\u0000-\u001f\u007f-\u009f\u2028\u2029]+/g, " ").replace(/\s+/g, " ").trim();
63	  return line.length > limit ? `${line.slice(0, limit - 1)}…` : line;
64	}
65	
66	/** The hooks running now, each as "kill its process group". One process listener serves them all, however many run. */
67	const running = new Set<() => void>();
68	let exitListening = false;
69	function killOnProcessExit(kill: () => void): () => void {
70	  if (!exitListening) {
71	    exitListening = true;
72	    process.on("exit", () => {
73	      for (const each of running) each();
74	    });
75	  }
76	  running.add(kill);
77	  return () => running.delete(kill);
78	}
79	
80	/** Runs the hook to its end. Never rejects: every way a run can go wrong is a `failure` on the result. */
81	export function runHookProcess(request: HookProcessRequest): Promise<HookProcessResult> {
82	  return new Promise((resolve) => {
83	    const started = Date.now();
84	    const killGraceMs = request.killGraceMs ?? HOOK_KILL_GRACE_MS;
85	    const [file, args] = typeof request.command === "string"
86	      ? ["/bin/sh", ["-c", request.command]]
87	      : [request.command[0].startsWith("~/") ? path.join(os.homedir(), request.command[0].slice(2)) : request.command[0], request.command.slice(1)];
88	    const out: Buffer[] = [];
89	    const err: Buffer[] = [];
90	    let outBytes = 0;
91	    let errBytes = 0;
92	    let failure: HookFailure | undefined;
93	    let detail: string | undefined;
94	    let settled = false;
95	    let exited: { code: number | null; signal: string | null } | undefined;
96	    let killTimer: NodeJS.Timeout | undefined;
97	    let drainTimer: NodeJS.Timeout | undefined;
98	    const tree = new ProcessTreeMemory();
99	
100	    let child: ReturnType<typeof spawn>;
101	    try {
102	      child = spawn(file, args, { cwd: request.cwd, env: request.env, detached: true, stdio: ["pipe", "pipe", "pipe"] });
103	    } catch (error) {
104	      resolve({ exit: null, signal: null, stdout: "", stderr: "", failure: "spawn", detail: error instanceof Error ? error.message : String(error), durationMs: 0 });
105	      return;
106	    }
107	
108	    // Once the hook has exited its pid may belong to another process: it is then neither signalled nor searched.
109	    const alivePid = () => (child.pid !== undefined && child.exitCode === null && child.signalCode === null ? child.pid : undefined);
110	    const signalAll = (name: NodeJS.Signals) => {
111	      const pid = alivePid();
112	      tree.remember(pid);
113	      if (pid !== undefined) {
114	        try {
115	          process.kill(-pid, name);
116	        } catch {
117	          // already gone
118	        }
119	      }
120	      // What left the group (its own session) is reached by pid, and only while it is still the process that was seen.
121	      tree.signal(name);
122	    };
123	    const finish = () => {
124	      if (settled) return;
125	      settled = true;
126	      clearTimeout(deadline);
127	      clearTimeout(killTimer);
128	      clearTimeout(drainTimer);
129	      forget();
130	      child.stdout?.destroy();
131	      child.stderr?.destroy();
132	      resolve({
133	        exit: exited?.code ?? null,
134	        signal: exited?.signal ?? null,
135	        stdout: Buffer.concat(out).toString("utf8"),
136	        stderr: Buffer.concat(err).toString("utf8"),
137	        ...(failure ? { failure } : {}),
138	        ...(detail ? { detail } : {}),
139	        durationMs: Date.now() - started,
140	      });
141	    };
142	    const stop = (why: HookFailure) => {
143	      if (failure || settled) return;
144	      failure = why;
145	      signalAll("SIGTERM");
146	      killTimer = setTimeout(() => {
147	        signalAll("SIGKILL");
148	        // A killed process exits; this only covers a pid that can no longer be waited for.
149	        killTimer = setTimeout(finish, killGraceMs);
150	      }, killGraceMs);
151	    };
152	    const onProcessExit = () => {
153	      const pid = alivePid();
154	      if (pid !== undefined) {
155	        try {
156	          process.kill(-pid, "SIGKILL");
157	        } catch {
158	          // already gone
159	        }
160	      }
161	    };
162	    const deadline = setTimeout(() => stop("timeout"), request.timeoutMs);
163	    const forget = killOnProcessExit(onProcessExit);
164	
165	    child.stdout!.on("data", (chunk: Buffer) => {
166	      if (failure) return;
167	      outBytes += chunk.length;
168	      if (outBytes > HOOK_STDOUT_LIMIT) return stop("stdout_oversize");
169	      out.push(chunk);
170	    });
171	    child.stderr!.on("data", (chunk: Buffer) => {
172	      if (failure) return;
173	      errBytes += chunk.length;
174	      if (errBytes > HOOK_STDERR_LIMIT) return stop("stderr_oversize");
175	      err.push(chunk);
176	    });
177	    // A hook that does not read its input closes the pipe early; that is its choice, not an error.
178	    child.stdin!.on("error", () => {});
179	    child.stdin!.end(request.stdin);
180	
181	    child.once("error", (error) => {
182	      failure ??= "spawn";
183	      detail = error.message;
184	      finish();
185	    });
186	    child.once("exit", (code, signal) => {
187	      exited = { code, signal };
188	      if (failure) {
189	        // The hook is over; what it started and left behind is not given the rest of the grace period.
190	        clearTimeout(killTimer);
191	        tree.remember(undefined);
192	        tree.signal("SIGKILL");
193	        return finish();
194	      }
195	      // Output may still be in the pipe. If something the hook started keeps the pipe open, the answer cannot be known
196	      // to be complete, and an incomplete answer must not read as "no objection".
197	      drainTimer = setTimeout(() => {
198	        failure = "output_left_open";
199	        finish();
200	      }, request.drainMs ?? HOOK_DRAIN_MS);
201	    });
202	    child.once("close", () => {
203	      if (exited) finish();
204	    });
205	  });
206	}
207	
208	export interface HookVerdict {
209	  decision: "none" | "deny" | "ignored_allow" | "error";
210	  /** Set for `deny` and `error`. */
211	  denialReason?: Exclude<HookDenialReason, "HOOKS_CONFIG_INVALID">;
212	  reason?: string;
213	  ignored?: string[];
214	}
215	
216	const DENY_DECISIONS = new Set(["block", "deny"]);
217	const ALLOW_DECISIONS = new Set(["approve", "allow"]);
218	const IGNORED_MEMBERS = ["updatedInput", "additionalContext", "suppressOutput", "systemMessage"];
219	const FAILURE_TEXT: Record<HookFailure, string> = {
220	  spawn: "the hook could not be started",
221	  timeout: "the hook did not finish in time and was stopped",
222	  stdout_oversize: `the hook wrote more than ${HOOK_STDOUT_LIMIT / 1024} KiB to standard output`,
223	  stderr_oversize: `the hook wrote more than ${HOOK_STDERR_LIMIT / 1024} KiB to standard error`,
224	  output_left_open: "the hook exited but something it started kept its output open, so its answer may be incomplete",
225	};
226	
227	/**
228	 * What a finished hook run means. Pure. `deny` and `error` both refuse a tool call before it runs (`error` is the
229	 * fail-closed case); `none` and `ignored_allow` leave the call as the gates decided it. No result admits anything.
230	 */
231	export function reduceHookOutput(result: Pick<HookProcessResult, "exit" | "signal" | "stdout" | "stderr" | "failure" | "detail">): HookVerdict {
232	  const error = (reason: string, denialReason: HookVerdict["denialReason"] = "HOOK_FAILED"): HookVerdict => ({ decision: "error", denialReason, reason: hookLine(reason) });
233	  if (result.failure) return error(`${FAILURE_TEXT[result.failure]}${result.detail ? ` (${result.detail})` : ""}`);
234	  if (result.signal) return error(`the hook was ended by ${result.signal}`);
235	  if (result.exit === 2) return { decision: "deny", denialReason: "HOOK_DENIED", reason: hookLine(result.stderr) || "the hook exited with status 2" };
236	  if (result.exit !== 0) return error(`the hook exited with status ${result.exit}`);
237	
238	  const text = result.stdout.trim();
239	  if (!text) return { decision: "none" };
240	  if (!text.startsWith("{")) return { decision: "none", reason: hookLine(text) };
241	  let answer: Record<string, unknown>;
242	  try {
243	    // The strict parser: with a repeated "decision" key, which one counts must not depend on the parser.
244	    answer = parseStrictJson(text, { maxDepth: 32 }) as Record<string, unknown>;
245	  } catch (problem) {
246	    return error(`the hook's output is not a valid JSON object: ${problem instanceof Error ? problem.message : String(problem)}`, "HOOK_OUTPUT_INVALID");
247	  }
248	  const specific = answer.hookSpecificOutput;
249	  if (specific !== undefined && (specific === null || typeof specific !== "object" || Array.isArray(specific))) return error("the hook's hookSpecificOutput is not an object", "HOOK_OUTPUT_INVALID");
250	  const nested = (specific ?? {}) as Record<string, unknown>;
251	  const text1 = (value: unknown) => (typeof value === "string" && value.trim() ? hookLine(value) : undefined);
252	
253	  const ignored = [
254	    ...IGNORED_MEMBERS.filter((key) => key in answer),
255	    ...IGNORED_MEMBERS.filter((key) => key in nested).map((key) => `hookSpecificOutput.${key}`),
256	  ];
257	  const withIgnored = (verdict: HookVerdict): HookVerdict => (ignored.length ? { ...verdict, ignored } : verdict);
258	  const deny = (reason: string | undefined, fallback: string): HookVerdict => withIgnored({ decision: "deny", denialReason: "HOOK_DENIED", reason: reason ?? fallback });
259	
260	  const { decision } = answer;
261	  const permission = nested.permissionDecision;
262	  // A denial anywhere in the answer wins over an allow anywhere else in it.
263	  if (typeof decision === "string" && DENY_DECISIONS.has(decision)) return deny(text1(answer.reason), `the hook answered ${decision}`);
264	  if (permission === "deny") return deny(text1(nested.permissionDecisionReason) ?? text1(answer.reason), "the hook answered deny");
265	  if (permission === "ask") return deny(text1(nested.permissionDecisionReason), "a hook asked for a human; this version treats ask as deny");
266	  if (answer.continue === false) return deny(text1(answer.stopReason) ?? text1(answer.reason), "the hook answered continue: false");
267	  // A decision this version does not know cannot be read as "no objection".
268	  if (decision !== undefined && !(typeof decision === "string" && ALLOW_DECISIONS.has(decision))) return withIgnored(error(`the hook's decision ${hookLine(JSON.stringify(decision), 80)} is not one of block, deny, approve, allow`, "HOOK_OUTPUT_INVALID"));
269	  if (permission !== undefined && permission !== "allow") return withIgnored(error(`the hook's permissionDecision ${hookLine(JSON.stringify(permission), 80)} is not one of allow, deny, ask`, "HOOK_OUTPUT_INVALID"));
270	  if (answer.continue !== undefined && answer.continue !== true) return withIgnored(error("the hook's continue is not true or false", "HOOK_OUTPUT_INVALID"));
271	  if (decision !== undefined || permission !== undefined) return withIgnored({ decision: "ignored_allow" });
272	  return withIgnored({ decision: "none" });
273	}
274	
275	/** SHA-256 of a hook's standard output: the receipt names what was said without keeping it. */
276	export function hookOutputDigest(stdout: string): string {
277	  return createHash("sha256").update(stdout).digest("hex");
278	}
