1	/**
2	 * HK-1: runs one command hook as a subprocess and reduces what it answered to a decision.
3	 *
4	 * The process gets the event as one JSON object on standard input, a scrubbed environment (no credentials of the
5	 * Nexus process), its own process group and a hard deadline. Its answer can only deny: `reduceHookOutput` has no
6	 * path from any output to "admit what was refused", and everything that goes wrong is a denial.
7	 */
8	import { spawn } from "node:child_process";
9	import { createHash } from "node:crypto";
10	import * as os from "node:os";
11	import * as path from "node:path";
12	import { buildMcpEnvironment } from "../mcp.js";
13	import type { HookDenialReason, HookEvent, HookSource } from "./hooks.js";
14	import { ProcessTreeMemory } from "./process_identity.js";
15	import { parseStrictJson } from "./strict_json.js";
16	
17	export const HOOK_STDOUT_LIMIT = 64 * 1024;
18	export const HOOK_STDERR_LIMIT = 8 * 1024;
19	/** Time a hook gets after SIGTERM before it and everything it started is killed. */
20	export const HOOK_KILL_GRACE_MS = 2_000;
21	/** Time a hook's output pipes may stay open after it exited (something it started still holds them). */
22	export const HOOK_DRAIN_MS = 2_000;
23	const REASON_LIMIT = 1000;
24	
25	export type HookFailure = "spawn" | "timeout" | "stdout_oversize" | "stderr_oversize" | "output_left_open";
26	
27	export interface HookProcessResult {
28	  exit: number | null;
29	  signal: string | null;
30	  stdout: string;
31	  stderr: string;
32	  /** Set when the run did not end as an ordinary exit with complete, bounded output. */
33	  failure?: HookFailure;
34	  detail?: string;
35	  durationMs: number;
36	}
37	
38	export interface HookProcessRequest {
39	  /** A string runs under `/bin/sh -c`; an array is executed directly. */
40	  command: string | string[];
41	  cwd: string;
42	  env: Record<string, string>;
43	  stdin: string;
44	  timeoutMs: number;
45	  killGraceMs?: number;
46	  drainMs?: number;
47	}
48	
49	/** The environment of a hook: the MCP server scrubber's safe variables plus the hook's own, and nothing else. */
50	export function hookEnvironment(hook: { event: HookEvent; name: string; source: HookSource; workspace: string }): Record<string, string> {
51	  return buildMcpEnvironment({
52	    NEXUS_HOOK_EVENT: hook.event,
53	    NEXUS_HOOK_NAME: hook.name,
54	    NEXUS_HOOK_SOURCE: hook.source,
55	    NEXUS_PROJECT_DIR: hook.workspace,
56	    CLAUDE_PROJECT_DIR: hook.workspace,
57	  });
58	}
59	
60	/** One line, bounded: what a hook said, safe to show and to store. */
61	export function hookLine(text: string, limit = REASON_LIMIT): string {
62	  const line = text.replace(/[\u0000-\u001f\u007f-\u009f\u2028\u2029]+/g, " ").replace(/\s+/g, " ").trim();
63	  return line.length > limit ? `${line.slice(0, limit - 1)}…` : line;
64	}
65	
66	/** The hooks running now, each as "kill its process group". One process listener serves them all, however many run. */
67	const running = new Set<() => void>();
68	let exitListening = false;
69	function killOnProcessExit(kill: () => void): () => void {
70	  if (!exitListening) {
71	    exitListening = true;
72	    process.on("exit", () => {
73	      for (const each of running) each();
74	    });
75	  }
76	  running.add(kill);
77	  return () => running.delete(kill);
78	}
