208	export interface HookVerdict {
209	  decision: "none" | "deny" | "ignored_allow" | "error";
210	  /** Set for `deny` and `error`. */
211	  denialReason?: Exclude<HookDenialReason, "HOOKS_CONFIG_INVALID">;
212	  reason?: string;
213	  ignored?: string[];
214	}
215	
216	const DENY_DECISIONS = new Set(["block", "deny"]);
217	const ALLOW_DECISIONS = new Set(["approve", "allow"]);
218	const IGNORED_MEMBERS = ["updatedInput", "additionalContext", "suppressOutput", "systemMessage"];
219	const FAILURE_TEXT: Record<HookFailure, string> = {
220	  spawn: "the hook could not be started",
221	  timeout: "the hook did not finish in time and was stopped",
222	  stdout_oversize: `the hook wrote more than ${HOOK_STDOUT_LIMIT / 1024} KiB to standard output`,
223	  stderr_oversize: `the hook wrote more than ${HOOK_STDERR_LIMIT / 1024} KiB to standard error`,
224	  output_left_open: "the hook exited but something it started kept its output open, so its answer may be incomplete",
225	};
226	
227	/**
228	 * What a finished hook run means. Pure. `deny` and `error` both refuse a tool call before it runs (`error` is the
229	 * fail-closed case); `none` and `ignored_allow` leave the call as the gates decided it. No result admits anything.
230	 */
231	export function reduceHookOutput(result: Pick<HookProcessResult, "exit" | "signal" | "stdout" | "stderr" | "failure" | "detail">): HookVerdict {
232	  const error = (reason: string, denialReason: HookVerdict["denialReason"] = "HOOK_FAILED"): HookVerdict => ({ decision: "error", denialReason, reason: hookLine(reason) });
233	  if (result.failure) return error(`${FAILURE_TEXT[result.failure]}${result.detail ? ` (${result.detail})` : ""}`);
234	  if (result.signal) return error(`the hook was ended by ${result.signal}`);
235	  if (result.exit === 2) return { decision: "deny", denialReason: "HOOK_DENIED", reason: hookLine(result.stderr) || "the hook exited with status 2" };
236	  if (result.exit !== 0) return error(`the hook exited with status ${result.exit}`);
237	
238	  const text = result.stdout.trim();
239	  if (!text) return { decision: "none" };
240	  if (!text.startsWith("{")) return { decision: "none", reason: hookLine(text) };
241	  let answer: Record<string, unknown>;
242	  try {
243	    // The strict parser: with a repeated "decision" key, which one counts must not depend on the parser.
244	    answer = parseStrictJson(text, { maxDepth: 32 }) as Record<string, unknown>;
245	  } catch (problem) {
246	    return error(`the hook's output is not a valid JSON object: ${problem instanceof Error ? problem.message : String(problem)}`, "HOOK_OUTPUT_INVALID");
247	  }
248	  const specific = answer.hookSpecificOutput;
249	  if (specific !== undefined && (specific === null || typeof specific !== "object" || Array.isArray(specific))) return error("the hook's hookSpecificOutput is not an object", "HOOK_OUTPUT_INVALID");
250	  const nested = (specific ?? {}) as Record<string, unknown>;
251	  const text1 = (value: unknown) => (typeof value === "string" && value.trim() ? hookLine(value) : undefined);
252	
253	  const ignored = [
254	    ...IGNORED_MEMBERS.filter((key) => key in answer),
255	    ...IGNORED_MEMBERS.filter((key) => key in nested).map((key) => `hookSpecificOutput.${key}`),
256	  ];
257	  const withIgnored = (verdict: HookVerdict): HookVerdict => (ignored.length ? { ...verdict, ignored } : verdict);
258	  const deny = (reason: string | undefined, fallback: string): HookVerdict => withIgnored({ decision: "deny", denialReason: "HOOK_DENIED", reason: reason ?? fallback });
259	
260	  const { decision } = answer;
261	  const permission = nested.permissionDecision;
262	  // A denial anywhere in the answer wins over an allow anywhere else in it.
263	  if (typeof decision === "string" && DENY_DECISIONS.has(decision)) return deny(text1(answer.reason), `the hook answered ${decision}`);
264	  if (permission === "deny") return deny(text1(nested.permissionDecisionReason) ?? text1(answer.reason), "the hook answered deny");
265	  if (permission === "ask") return deny(text1(nested.permissionDecisionReason), "a hook asked for a human; this version treats ask as deny");
266	  if (answer.continue === false) return deny(text1(answer.stopReason) ?? text1(answer.reason), "the hook answered continue: false");
267	  // A decision this version does not know cannot be read as "no objection".
268	  if (decision !== undefined && !(typeof decision === "string" && ALLOW_DECISIONS.has(decision))) return withIgnored(error(`the hook's decision ${hookLine(JSON.stringify(decision), 80)} is not one of block, deny, approve, allow`, "HOOK_OUTPUT_INVALID"));
269	  if (permission !== undefined && permission !== "allow") return withIgnored(error(`the hook's permissionDecision ${hookLine(JSON.stringify(permission), 80)} is not one of allow, deny, ask`, "HOOK_OUTPUT_INVALID"));
270	  if (answer.continue !== undefined && answer.continue !== true) return withIgnored(error("the hook's continue is not true or false", "HOOK_OUTPUT_INVALID"));
271	  if (decision !== undefined || permission !== undefined) return withIgnored({ decision: "ignored_allow" });
272	  return withIgnored({ decision: "none" });
273	}
