1	/**
2	 * `nexus hooks`: list the command hooks in force, approve or revoke a project's hooks file, and try the configured
3	 * hooks against a sample tool call (HK-1). Approving records the SHA-256 of the exact bytes shown, and of the workspace
4	 * files the hooks run. It is the act of a person: there is no `--yes`, and without a terminal nothing is approved.
5	 */
6	import * as path from "node:path";
7	import type { Command } from "commander";
8	import pc from "picocolors";
9	import { createDefaultRegistry } from "./core/capabilities.js";
10	import { approveExtension, extensionTrustStorePath, revokeExtension } from "./core/content_trust.js";
11	import { HOOK_DEFAULT_TIMEOUT_SECS, HOOK_EVENTS, HookRegistry, inspectHookSources, type HookDeclaration, type HookEvent, type HooksFile, type HookSources, type LoadedHooksFile } from "./core/hooks.js";
12	import { hookLine } from "./core/hook_runner.js";
13	import { parseStrictJson } from "./core/strict_json.js";
