15	export interface HookCliDeps {
16	  /** Asks a yes/no question on the terminal. */
17	  confirm?: (question: string) => Promise<boolean>;
18	  /** Whether there is a terminal to ask on. */
19	  interactive?: () => boolean;
20	}
21	
22	async function confirmOnTerminal(question: string): Promise<boolean> {
23	  const readline = await import("node:readline/promises");
24	  const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
25	  try {
26	    return /^y(es)?$/i.test((await rl.question(question)).trim());
27	  } finally {
28	    rl.close();
29	  }
30	}
