32	const workspaceOf = (options: { workspace?: string }) => path.resolve(options.workspace ?? process.cwd());
33	const hooksOf = (file: HooksFile): Array<{ event: HookEvent; hook: HookDeclaration }> => HOOK_EVENTS.flatMap((event) => (file.hooks[event] ?? []).map((hook) => ({ event, hook })));
34	const commandText = (command: string | string[]) => hookLine(typeof command === "string" ? `sh -c ${JSON.stringify(command)}` : command.map((part) => JSON.stringify(part)).join(" "), 300);
35	
36	/** Tool names a hook lists that no built-in tool has: most likely a typing error, and such a hook never runs. */
37	function unknownTools(file: HooksFile): string[] {
38	  const registry = createDefaultRegistry();
39	  const names = hooksOf(file).flatMap(({ hook }) => hook.tools).filter((name) => name !== "*" && !name.startsWith("mcp__") && !registry.getByToolName(name));
40	  return [...new Set(names)];
41	}
