43	interface ListedSource {
44	  source: "operator" | "project";
45	  path: string;
46	  status: "absent" | "active" | "not_approved" | "changed" | "invalid" | "read_only";
47	  sha256?: string;
48	  problem?: string;
49	  hooks: Array<{ event: HookEvent; name: string; tools: string[]; command: string | string[]; timeout_secs: number }>;
50	  unknown_tools?: string[];
51	  /** Project only: the workspace files its commands run, whose bytes an approval covers. */
52	  covered_files?: Array<{ path: string; sha256: string }>;
53	  /** Project only, status `changed`: what differs from the approval. */
54	  changed?: string[];
55	}
56	
57	function listed(source: "operator" | "project", file: string, loaded: LoadedHooksFile, status: ListedSource["status"]): ListedSource {
58	  const unknown = loaded.state === "ok" ? unknownTools(loaded.file) : [];
59	  return {
60	    source,
61	    path: file,
62	    status,
63	    ...(loaded.state !== "absent" && loaded.sha256 ? { sha256: loaded.sha256 } : {}),
64	    ...(loaded.state === "invalid" ? { problem: loaded.problem } : {}),
65	    hooks: loaded.state === "ok" ? hooksOf(loaded.file).map(({ event, hook }) => ({ event, name: hook.name, tools: hook.tools, command: hook.command, timeout_secs: hook.timeout_secs ?? HOOK_DEFAULT_TIMEOUT_SECS })) : [],
66	    ...(unknown.length ? { unknown_tools: unknown } : {}),
67	  };
68	}
