70	/** Both sources as `nexus hooks list` shows them. */
71	export function listHookSources(sources: HookSources): ListedSource[] {
72	  const operator = sources.operator.loaded;
73	  return [
74	    listed("operator", sources.operator.path, operator, operator.state === "absent" ? "absent" : operator.state === "ok" ? "active" : "invalid"),
75	    {
76	      ...listed("project", sources.project.path, sources.project.loaded, sources.project.status),
77	      // The project's own reason (a command that cannot be pinned) when the file itself parsed.
78	      ...(sources.project.problem ? { problem: sources.project.problem } : {}),
79	      ...(sources.project.files.length ? { covered_files: sources.project.files } : {}),
80	      ...(sources.project.changed ? { changed: sources.project.changed } : {}),
81	    },
82	  ];
83	}
84	
85	function printSource(entry: ListedSource): void {
86	  const colour = entry.status === "active" ? pc.green : entry.status === "absent" ? pc.dim : pc.yellow;
87	  console.log(`${pc.bold(entry.source)}  ${entry.path}  ${colour(entry.status)}${entry.sha256 ? pc.dim(`  sha256 ${entry.sha256}`) : ""}`);
88	  if (entry.problem) console.log(`  ${pc.red(hookLine(entry.problem))}`);
89	  for (const hook of entry.hooks) {
90	    console.log(`  ${hook.event}  ${pc.bold(hook.name)}  tools: ${hook.tools.join(", ")}  timeout: ${hook.timeout_secs}s`);
91	    console.log(`    ${commandText(hook.command)}`);
92	  }
93	  for (const file of entry.covered_files ?? []) console.log(pc.dim(`  covers ${file.path}  sha256 ${file.sha256}`));
94	  if (entry.changed) console.log(pc.yellow(`  changed since approval: ${entry.changed.join(", ")}`));
95	  if (entry.unknown_tools) console.log(pc.yellow(`  no built-in tool is named ${entry.unknown_tools.join(", ")}: a hook that lists only such names never runs`));
96	}
