98	/** A person can be asked only when both ends are a terminal: input alone can be a pipe's reader, output alone a log. */
99	export function isInteractiveTerminal(stdin: { isTTY?: boolean } = process.stdin, stdout: { isTTY?: boolean } = process.stdout): boolean {
100	  return Boolean(stdin.isTTY) && Boolean(stdout.isTTY);
101	}
