103	export function registerHookCommands(program: Command, deps: HookCliDeps = {}): void {
104	  const confirm = deps.confirm ?? confirmOnTerminal;
105	  const interactive = deps.interactive ?? (() => isInteractiveTerminal());
106	  const hooks = program.command("hooks").description("Command hooks that run before and after tool calls (they can deny a call, never approve one)");
107	
108	  hooks
109	    .command("list")
110	    .description("Show the operator's and the project's hooks and whether they are in force")
111	    .option("-w, --workspace <path>", "Workspace directory (default: current directory)")
112	    .option("-j, --json", "Print the listing as JSON")
113	    .action((options: { workspace?: string; json?: boolean }) => {
114	      const sources = inspectHookSources({ workspace: workspaceOf(options), readOnly: false });
115	      const entries = listHookSources(sources);
116	      if (options.json) {
117	        console.log(JSON.stringify({ sources: entries, ...(sources.trustProblem ? { trust_store_problem: sources.trustProblem } : {}) }, null, 2));
118	      } else {
119	        for (const entry of entries) printSource(entry);
120	        if (sources.trustProblem) console.log(pc.yellow(`The approval store ${extensionTrustStorePath()} is not used: ${sources.trustProblem}. Nothing it approved runs.`));
121	        if (entries[0].status === "invalid") console.log(pc.red("The operator's hooks file is invalid: every tool call is denied until it is fixed or moved aside."));
122	        if (entries[1].status === "not_approved" || entries[1].status === "changed") console.log(`The project's hooks do not run${entries[1].status === "changed" ? ` (${entries[1].changed?.join(", ")} changed since the approval)` : ""}. Review them, then run \`nexus hooks approve\` in a terminal.`);
123	      }
124	      // An invalid operator file stops all work, so a script that lists hooks should notice.
125	      if (entries[0].status === "invalid") process.exitCode = 1;
126	    });
127	
128	  hooks
129	    .command("approve")
130	    .description("Approve this workspace's .nexus/hooks.json as it is now (a later change needs a new approval)")
131	    .option("-w, --workspace <path>", "Workspace directory (default: current directory)")
132	    .option("--sha256 <hex>", "Approve only if the file has this SHA-256 (you are still asked; approving needs a terminal)")
133	    .action(async (options: { workspace?: string; sha256?: string }) => {
134	      const { project } = inspectHookSources({ workspace: workspaceOf(options), readOnly: false });
135	      const refuse = (message: string, code = 1) => {
136	        console.error(pc.red(message));
137	        process.exitCode = code;
138	      };
139	      if (project.loaded.state === "absent") return refuse(`There is no ${project.path}.`);
140	      if (project.loaded.state === "invalid" || project.status === "invalid") return refuse(`${project.path} is not a valid hooks file and cannot be approved: ${hookLine(project.problem ?? "")}`);
141	      const { sha256, file } = project.loaded;
142	      const entry = listed("project", project.path, project.loaded, project.status);
143	      console.log(`${project.path}\nsha256 ${sha256}\nThese programs would run with your authority, outside the sandbox, on the tool calls they name:`);
144	      for (const hook of entry.hooks) console.log(`  ${hook.event}  ${hook.name}  tools: ${hook.tools.join(", ")}\n    ${commandText(hook.command)}`);
145	      if (!entry.hooks.length) console.log("  (no hooks)");
146	      if (project.files.length) console.log("The approval also covers these workspace files they run, as they are now (a change to one needs a new approval):");
147	      for (const covered of project.files) console.log(`  ${covered.path}  sha256 ${covered.sha256}`);
148	
149	      // Approving is the act of a person: a tool call of the agent has no terminal, and must not be able to approve
150	      // hooks for itself by naming a hash.
151	      if (!interactive()) {
152	        return refuse("Not approved: approving hooks needs a person at a terminal (standard input and output are not both a terminal). Review the file, then run `nexus hooks approve` yourself in a terminal.", 2);
153	      }
154	      const pinned = options.sha256?.trim().toLowerCase();
155	      if (pinned !== undefined && pinned !== sha256) return refuse(`Not approved: --sha256 does not match the file, whose SHA-256 is ${sha256}.`, 2);
156	      if (!(await confirm("Approve these hooks for this workspace? [y/N] "))) return refuse("Not approved.");
157	      // What is recorded is what was read and shown above, not the files as they may be now.
158	      const count = hooksOf(file).length;
159	      approveExtension({ kind: "project-hooks", scope: project.id.scope, key: project.id.key, sha256, approvedAt: new Date().toISOString(), summary: `${count} hook${count === 1 ? "" : "s"}`, ...(project.files.length ? { files: project.files } : {}) });
160	      console.log(`Approved for ${project.id.scope}. Undo with \`nexus hooks revoke\`.`);
161	    });
162	
163	  hooks
164	    .command("revoke")
165	    .description("Withdraw the approval of this workspace's .nexus/hooks.json")
166	    .option("-w, --workspace <path>", "Workspace directory (default: current directory)")
167	    .action((options: { workspace?: string }) => {
168	      const { project } = inspectHookSources({ workspace: workspaceOf(options), readOnly: false });
169	      console.log(revokeExtension(project.id) ? `No longer approved: ${project.path}` : `There was no approval for ${project.path}.`);
170	    });
171	
172	  hooks
173	    .command("test")
174	    .description("Run the hooks in force against a sample tool call and print what they decide (the tool itself is not run)")
175	    .argument("<event>", HOOK_EVENTS.join(" or "))
176	    .requiredOption("--tool <name>", "Tool name of the sample call, for example run_command")
177	    .option("--input <json>", "The sample call's arguments as a JSON object", "{}")
178	    .option("--response <json>", "post-tool only: the sample result as a JSON object with success, output and error", '{"success":true,"output":"","error":null}')
179	    .option("-w, --workspace <path>", "Workspace directory (default: current directory)")
180	    .option("-j, --json", "Print the result as JSON")
181	    .action(async (event: string, options: { tool: string; input: string; response: string; workspace?: string; json?: boolean }) => {
182	      const usage = (message: string) => {
183	        console.error(pc.red(message));
184	        process.exitCode = 1;
185	      };
186	      if (!(HOOK_EVENTS as readonly string[]).includes(event)) return usage(`Unknown event '${hookLine(event, 60)}': use ${HOOK_EVENTS.join(" or ")}.`);
187	      const object = (text: string, what: string): Record<string, unknown> | undefined => {
188	        try {
189	          const value = parseStrictJson(text, { maxDepth: 32 });
190	          if (value && typeof value === "object" && !Array.isArray(value)) return value as Record<string, unknown>;
191	        } catch {
