197	      const input = object(options.input, "--input");
198	      const response = input && object(options.response, "--response");
199	      if (!input || !response) return;
200	
201	      const workspace = workspaceOf(options);
202	      const notices: string[] = [];
203	      const registry = new HookRegistry({ workspace: () => workspace, readOnly: () => false, permissionMode: () => "review", sessionId: () => "hooks-test", notify: (text) => notices.push(text) });
204	      const result = await registry.tryEvent(event as HookEvent, options.tool, input, { success: response.success !== false, output: String(response.output ?? ""), error: typeof response.error === "string" ? response.error : null });
205	      if (options.json) {
206	        console.log(JSON.stringify({ event, tool: options.tool, decision: result.admitted ? "none" : "deny", ...(result.denialReason ? { denial_reason: result.denialReason } : {}), ...(result.reason ? { reason: result.reason } : {}), runs: result.runs, notices }, null, 2));
